function login() {
  var data = result;
  var loginName = '';
  var password = '';
  try {
    if (data) {
      if (typeof data.get === 'function') {
        loginName = String(data.get('loginName') || '');
        password = String(data.get('password') || '');
      } else {
        loginName = String(data.loginName || '');
        password = String(data.password || '');
      }
    }
  } catch (e) {}
  if (!loginName) {
    try {
      var info = source.getLoginInfoMap();
      if (info) {
        loginName = String(info.get('loginName') || '');
        password = String(info.get('password') || '');
      }
    } catch (e2) {}
  }
  loginName = String(loginName || '').trim();
  password = String(password || '');
  if (!loginName || loginName.indexOf('@') < 0) {
    java.toast('请填写正确的邮箱');
    return false;
  }
  if (password.length < 6) {
    java.toast('密码至少 6 位');
    return false;
  }
  var body = 'loginName=' + encodeURIComponent(loginName) + '&password=' + encodeURIComponent(password);
  var headers = {
    'Content-Type': 'application/x-www-form-urlencoded',
    'User-Agent': java.getWebViewUA(),
    'Referer': 'https://www.banshanren.com/',
    'Origin': 'https://www.banshanren.com'
  };
  var text = '';
  try {
    var resp = java.post('https://www.banshanren.com/login', body, headers);
    text = String(resp && resp.body ? resp.body() : (resp || ''));
  } catch (e3) {
    java.toast('请求失败: ' + e3);
    return false;
  }
  if (/"result"\s*:\s*"success"/.test(text)) {
    java.toast('登录成功');
    return true;
  }
  var msg = (text.match(/"msg"\s*:\s*"([^"]+)"/) || [])[1] || '登录失败';
  java.toast(msg);
  return false;
}

